// src/app/landwirte/page.js – Landwirte & Agri-PV: die vier Wege

import { BatteryCharging, CalendarClock, CloudHail, Compass, Scale, ShieldCheck, Sprout, TrendingUp, Users, Warehouse, Wheat } from "lucide-react";

import Section from "@/components/ui/Section";
import SectionHeading, { Eyebrow } from "@/components/ui/SectionHeading";
import Reveal from "@/components/ui/Reveal";
import Faq from "@/components/ui/Faq";
import CtaBand from "@/components/ui/CtaBand";
import Querverweise from "@/components/Reusable/Querverweise";
import AnfrageFormular from "@/components/Plattform/AnfrageFormular";
import WegeEntscheider from "@/components/Agri/WegeEntscheider";
import AgriBild from "@/components/Agri/AgriBild";
import { WEGE } from "@/components/Agri/wege";
import AgriHero from "@/components/Agri/Seite/AgriHero";
import WegeBuehne from "@/components/Agri/Seite/WegeBuehne";
import WegeKarten from "@/components/Agri/Seite/WegeKarten";
import Faktenleiste from "@/components/Agri/Seite/Faktenleiste";
import Sprungleiste from "@/components/Agri/Seite/Sprungleiste";
import { abs } from "@/data/site";
import { AGRI, PACHT, STAND, STROM } from "@/lib/invest/markt";
import { fmt } from "@/lib/rechner/annahmen";

const PFAD = "/landwirte";
const TITEL = "Agri-PV für Landwirte: vier Wege zum Solarstrom | ÖkoInvest";
const BESCHREIBUNG =
  "Fläche verpachten, selbst investieren, Investor baut oder Genossenschaft: die vier Wege zu Agri-PV für Landwirte im Vergleich – mit Entscheidungshilfe.";

export const metadata = {
  title: TITEL,
  description: BESCHREIBUNG,
  alternates: { canonical: abs(PFAD) },
  openGraph: {
    type: "website",
    locale: "de_DE",
    url: abs(PFAD),
    siteName: "ÖkoInvest",
    title: TITEL,
    description: BESCHREIBUNG,
    images: [{ url: abs("/img/freiflaeche-begehung.jpg"), width: 1280, height: 852, alt: "Begehung einer landwirtschaftlichen Fläche" }],
  },
};

const ZEILEN = [
  ["Eigene Investition", "invest"],
  ["Einnahmen", "einnahmen"],
  ["Risiko", "risiko"],
  ["Landwirtschaft", "bewirtschaftung"],
  ["Ihr Aufwand", "aufwand"],
  ["Passt für", "fuer"],
];

const GRUENDE = [
  { icon: TrendingUp, title: "Zweites Standbein", text: "Pacht oder Stromerlöse fließen jährlich – unabhängig von Ernte, Getreidepreis und Witterung." },
  { icon: Scale, title: "Risikostreuung", text: "Strom und Ernte auf derselben Fläche: Fällt eines schwächer aus, trägt das andere. Die Fläche bleibt Ihr Betriebsmittel." },
  { icon: CloudHail, title: "Schutz für Kulturen", text: "Hoch aufgeständerte Module schützen Obst und Beeren vor Hagel, Starkregen und Sonnenbrand; der Boden verdunstet weniger Wasser." },
  { icon: BatteryCharging, title: "Eigenstrom für den Hof", text: "Melktechnik, Kühlung, Lüftung, Trocknung: Bei hofnahen Anlagen kann Solarstrom direkt im Betrieb genutzt werden." },
  { icon: Warehouse, title: "Hofnachfolge stärken", text: "Ein planbares Zusatzeinkommen macht den Betrieb für die nächste Generation attraktiver – ohne die Fläche abzugeben." },
  { icon: Users, title: "Akzeptanz im Dorf", text: "Agri-PV erhält die Landwirtschaft sichtbar. Mit der Genossenschaft können Nachbarn und Gemeinde mitverdienen." },
];

const SCHRITTE = [
  "Fläche, Kulturen, Maschinenbreiten und Netz – wir prüfen alles vorab",
  "Wir stimmen uns mit Landwirtschaftsamt und Gemeinde ab",
  "Status, Unterlagen und Nachrichten später im Portal",
];

const FAQ = [
  {
    q: "Welcher der vier Wege bringt am meisten?",
    a: "Je Hektar bringt die Pacht für einen klassischen Solarpark meist die höchste feste Zahlung – dafür endet die Bewirtschaftung. Bei Agri-PV ist die Pacht niedriger, Sie ernten aber weiter und behalten den größten Teil der Direktzahlungen. Eine Eigeninvestition hat die höchsten Chancen, aber auch das unternehmerische Risiko. Der Agri-PV-Rechner stellt die Wege mit Ihren Zahlen nebeneinander.",
  },
  {
    q: "Verliere ich mit Agri-PV meine Direktzahlungen?",
    a: `In Deutschland in der Regel nicht vollständig: Flächen mit Agri-PV nach DIN SPEC 91434 bleiben unter Voraussetzungen beihilfefähig, üblicherweise mit einem Abzug für die durch die Anlage nicht nutzbare Fläche – rechnerisch bleiben etwa ${fmt(AGRI.gapFoerderfaehig * 100)} % förderfähig. Maßgeblich sind die aktuellen GAP-Regeln; klären Sie den Einzelfall vorab mit Ihrem Landwirtschaftsamt.`,
  },
  {
    q: "Wie funktioniert die Beteiligung über die Genossenschaft?",
    a: "Die Anlage gehört ganz oder teilweise einer Energiegenossenschaft. Sie werden Mitglied, zeichnen Anteile und erhalten neben der Pacht eine Ausschüttung, deren Höhe von Ertrag und Beschlüssen der Generalversammlung abhängt. Nachbarn und Gemeinde können ebenfalls Mitglied werden. Jedes Mitglied hat in der Regel eine Stimme, unabhängig von der Zahl der Anteile.",
  },
  {
    q: "Kann ich den Strom selbst auf dem Hof nutzen?",
    a: `Das hängt vom Anschlusskonzept ab. Liegt die Anlage nah am Hof und gehört Ihnen (Weg B), kann ein Teil des Stroms direkt in Stall, Kühlung oder Trocknung fließen. Land- und forstwirtschaftliche Betriebe profitieren zudem seit 2026 von der auf ${fmt(STROM.stromsteuerProduzierend, 2)} ct/kWh gesenkten Stromsteuer. Bei großen Anlagen wird der Strom meist vollständig eingespeist und direkt vermarktet.`,
  },
  {
    q: "Brauche ich für Agri-PV einen Bebauungsplan?",
    a: `Nicht immer. Agri-PV-Anlagen bis ${fmt(AGRI.privilegierungHa, 1)} ha Grundfläche im räumlich-funktionalen Zusammenhang mit einem landwirtschaftlichen Betrieb sind im Außenbereich privilegiert (§ 35 BauGB) – eine Anlage je Hofstelle. Größere Anlagen brauchen in der Regel einen Bebauungsplan der Gemeinde.`,
  },
  {
    q: "Was bedeutet Agri-PV für Hofnachfolge und Erbschaft?",
    a: "Eine Agri-PV-Anlage kann die Hofnachfolge stärken: Sie bringt ein zweites, wetterunabhängiges Einkommen und die Fläche bleibt landwirtschaftlich genutzt. Steuerlich ist Agri-PV oft günstiger zu gestalten als ein klassischer Solarpark, weil die landwirtschaftliche Nutzung erhalten bleibt – die Details sind aber komplex und sollten mit der Steuerberatung geklärt werden.",
  },
];

export default function LandwirtePage() {
  return (
    <div>
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{
          __html: JSON.stringify({
            "@context": "https://schema.org",
            "@type": "Service",
            name: "Agri-PV und Solarprojekte für landwirtschaftliche Betriebe",
            provider: { "@id": `${abs("/")}/#organization` },
            areaServed: ["DE", "AT", "CH"],
            audience: { "@type": "Audience", audienceType: "Landwirtinnen und Landwirte" },
            url: abs(PFAD),
            description: BESCHREIBUNG,
          }),
        }}
      />

      <AgriHero
        breadcrumbs={[{ name: "Für Landwirte" }]}
        pill={{ href: "#entscheider", marke: "Tipp", text: "Entscheidungshilfe: Welcher Weg passt zu Ihrem Betrieb?", textKurz: "Welcher Weg passt zu Ihnen?" }}
        titel={
          <>
            Agri-PV: Die Ernte bleibt. <span className="ov-text-gradient-light">Strom kommt dazu.</span>
          </>
        }
        lead="Agri-PV macht Ihre Fläche zum zweiten Standbein – ohne die Landwirtschaft aufzugeben. Verpachten, selbst investieren, einen Investor bauen lassen oder über die Genossenschaft mitverdienen: Sie wählen den Weg, wir setzen ihn um."
        aktionen={[
          { label: "Welcher Weg passt?", href: "#entscheider" },
          { label: "Agri-PV-Rechner", href: "/rechner/agri-pv" },
        ]}
        unterzeile="Für Landwirte kostenfrei · fünf Fragen, eine Empfehlung mit Begründung"
        punkte={["Nach DIN SPEC 91434", "GAP bleibt größtenteils", "Deutschland, Österreich und Schweiz", "Von der Idee bis zum Betrieb"]}
        buehne={
          <WegeBuehne
            bild={{ src: "/img/freiflaeche-begehung.jpg", alt: "Begehung einer landwirtschaftlichen Fläche mit Photovoltaik", position: "center 55%" }}
            notiz={{ marke: "Wege B–D", titel: "Sie ernten weiter", text: "auf rund 85–90 % der Fläche" }}
          />
        }
      />

      <Faktenleiste
        titel="Agri-PV für Landwirte: Richtwerte"
        fakten={[
          { icon: Compass, wert: "4", einheit: "Wege", text: "Verpachten, selbst investieren, Investor oder Genossenschaft" },
          { icon: Wheat, wert: "85–90", suffix: "%", einheit: "Fläche bewirtschaftet", text: "bei Agri-PV (Wege B–D) bleibt der Großteil in Ihrer Hand" },
          { icon: ShieldCheck, wert: fmt(AGRI.gapFoerderfaehig * 100), suffix: "%", einheit: "GAP-förderfähig", text: "der Fläche bleiben in Deutschland rechnerisch beihilfefähig" },
          { icon: CalendarClock, wert: "30", suffix: "Jahre", einheit: "Planbares Einkommen", text: "aus Pacht oder Strom – weitgehend unabhängig von der Ernte" },
        ]}
      />

      <Sprungleiste
        ziele={[
          { href: "#wege", label: "Die vier Wege" },
          { href: "#vergleich", label: "Vergleich" },
          { href: "#warum", label: "Warum Agri-PV" },
          { href: "#entscheider", label: "Entscheidungshilfe" },
          { href: "#anfrage", label: "Anfrage" },
          { href: "#fragen", label: "Fragen" },
        ]}
      />

      {/* Vier Wege */}
      <Section tone="white" space="lg" id="wege" className="scroll-mt-24">
        <div className="mb-10 grid gap-x-16 gap-y-6 md:mb-14 lg:grid-cols-[minmax(0,1fr)_minmax(0,1fr)] lg:items-end">
          <SectionHeading eyebrow="Die vier Wege" title="Vier Wege – ein Ziel: Ihr Hof verdient mit." />
          <Reveal delay={80}>
            <p className="ov-lead text-pretty text-ink-600">Jeder Weg hat seine Stärken. Viele Betriebe kombinieren sie auch – etwa eine Fläche verpachten und bei einer anderen über die Genossenschaft einsteigen.</p>
          </Reveal>
        </div>
        <WegeKarten />

        {/* Vergleichstabelle */}
        <div id="vergleich" className="scroll-mt-24 pt-16 md:pt-20">
          <div className="mb-6 flex flex-wrap items-end justify-between gap-x-6 gap-y-1">
            <h3 className="ov-h3 text-ink-900">Die Wege im direkten Vergleich</h3>
            <p className="text-[14px] text-ink-500">Orientierungswerte DACH, Stand {STAND}</p>
          </div>
          <Reveal className="overflow-hidden rounded-[1.75rem] bg-white shadow-e2 ring-1 ring-ink-200/70">
            <div className="overflow-x-auto">
              <table className="w-full min-w-[820px] border-collapse text-left text-[14.5px]">
                <caption className="sr-only">Die vier Wege im Vergleich</caption>
                <thead>
                  <tr className="bg-navy-950 text-white">
                    <th scope="col" className="w-[15%] px-5 py-4 font-semibold">
                      <span className="sr-only">Merkmal</span>
                    </th>
                    {WEGE.map((w) => (
                      <th key={w.id} scope="col" className="px-5 py-4 align-bottom font-display text-[15.5px] font-bold">
                        <span className="mr-2 inline-flex h-7 w-7 items-center justify-center rounded-lg bg-ov-400/20 text-[13px] text-ov-300 ring-1 ring-inset ring-ov-300/30">{w.buchstabe}</span>
                        {w.titel}
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {ZEILEN.map(([label, key], i) => (
                    <tr key={key} className={i % 2 ? "bg-sand-50" : "bg-white"}>
                      <th scope="row" className="sticky left-0 bg-inherit px-5 py-3.5 align-top font-semibold text-ink-800">
                        {label}
                      </th>
                      {WEGE.map((w) => (
                        <td key={w.id} className="px-5 py-3.5 align-top leading-snug text-ink-600">
                          {w[key]}
                        </td>

// src/app/flaeche-verpachten/page.js – Landingpage für Flächeneigentümer

import { CalendarClock, HandCoins, Landmark, Wallet } from "lucide-react";

import Section from "@/components/ui/Section";
import SectionHeading from "@/components/ui/SectionHeading";
import Faq from "@/components/ui/Faq";
import CtaBand from "@/components/ui/CtaBand";
import Querverweise from "@/components/Reusable/Querverweise";
import { Faktenleiste } from "@/components/Flaeche/Seite/teile";
import Hero from "@/components/Flaeche/Verpachten/Hero";
import Pachtmodelle from "@/components/Flaeche/Verpachten/Pachtmodelle";
import { Steuern, Vertrag } from "@/components/Flaeche/Verpachten/Vertrag";
import { Anfrage, Pruefung, Weg } from "@/components/Flaeche/Verpachten/Ablauf";
import { abs } from "@/data/site";
import { PACHT, PROVISION } from "@/lib/invest/markt";
import { fmt } from "@/lib/rechner/annahmen";

const PFAD = "/flaeche-verpachten";
const TITEL = "Fläche für Solarpark verpachten | ÖkoInvest";
const BESCHREIBUNG =
  "Acker oder Grünland für einen Solarpark verpachten: Pachtmodelle, Vertrag, Rückbausicherheit, Steuern und Ablauf bis zur ersten Pacht. Jetzt Fläche melden.";

export const metadata = {
  title: TITEL,
  description: BESCHREIBUNG,
  alternates: { canonical: abs(PFAD) },
  openGraph: {
    type: "website",
    locale: "de_DE",
    url: abs(PFAD),
    siteName: "ÖkoInvest",
    title: TITEL,
    description: BESCHREIBUNG,
    images: [{ url: abs("/img/freiflaeche-begehung.jpg"), width: 1280, height: 852, alt: "Begehung einer Fläche für einen Solarpark" }],
  },
};

const FAKTEN = [
  { icon: Wallet, wert: `${fmt(PACHT.freiflaecheProHa.min)}–${fmt(PACHT.freiflaecheProHa.max)}`, einheit: "€ je Hektar und Jahr", text: `übliche Solarpacht im DACH-Raum, typisch um ${fmt(PACHT.freiflaecheProHa.mittel)} €` },
  { icon: CalendarClock, wert: `${PACHT.laufzeit} J.`, einheit: "Laufzeit", text: `ab Inbetriebnahme, dazu ${PACHT.verlaengerung}` },
  { icon: HandCoins, wert: `${fmt(PACHT.reservierungProHa.min)}–${fmt(PACHT.reservierungProHa.max)} €`, einheit: "Reservierungsprämie", text: "je Hektar und Jahr bis Baubeginn – Sie bewirtschaften weiter" },
  { icon: Landmark, wert: "0 €", einheit: "Kosten für Sie", text: `Prüfung, Angebot, Vertrag und Notar – ${PROVISION.flaeche.text}` },
];

const FAQ = [
  {
    q: "Wie viel Pacht bekomme ich für einen Solarpark?",
    a: `Für Freiflächen-PV liegen die Pachten im DACH-Raum derzeit meist zwischen ${fmt(PACHT.freiflaecheProHa.min)} und ${fmt(PACHT.freiflaecheProHa.max)} € je Hektar und Jahr, typisch um ${fmt(PACHT.freiflaecheProHa.mittel)} €. Entscheidend sind Netzanschluss, Größe, Einstrahlung und ob die Fläche in der EEG-Kulisse liegt. Das ist ein Vielfaches der üblichen Ackerpacht von durchschnittlich rund ${fmt(PACHT.ackerProHa)} € je Hektar.`,
  },
  {
    q: "Kostet mich die Prüfung oder der Vertrag etwas?",
    a: `Nein. ${PROVISION.flaeche.text[0].toUpperCase()}${PROVISION.flaeche.text.slice(1)} – Flächencheck, Pachtangebot, Vertragsentwurf und Notartermin für die Dienstbarkeit tragen wir. Eine anwaltliche oder steuerliche Prüfung auf Ihrer Seite empfehlen wir ausdrücklich; auf Wunsch beteiligen wir uns an den Kosten.`,
  },
  {
    q: "Ab wann wird die Pacht gezahlt?",
    a: `Die volle Pacht beginnt in der Regel mit Baubeginn oder Inbetriebnahme. Bis dahin – meist 2 bis 4 Jahre – zahlen wir eine Reservierungsprämie von typischerweise ${fmt(PACHT.reservierungProHa.min)}–${fmt(PACHT.reservierungProHa.max)} € je Hektar und Jahr, und Sie bewirtschaften die Fläche weiter wie bisher.`,
  },
  {
    q: "Was passiert, wenn der Solarpark doch nicht gebaut wird?",
    a: "Dann endet der Vertrag nach Ablauf einer vereinbarten Frist automatisch oder durch Rücktritt, die Dienstbarkeit wird gelöscht und Sie haben Ihre Fläche uneingeschränkt zurück. Bereits gezahlte Reservierungsprämien behalten Sie.",
  },
  {
    q: "Kann ich die Fläche während der Laufzeit verkaufen oder vererben?",
    a: "Ja. Der Pachtvertrag und die Dienstbarkeit im Grundbuch gehen auf Käufer oder Erben über – die Pacht auch. Für die Erbschaftsteuer kann die Verpachtung an einen Solarpark allerdings nachteilig sein; lassen Sie das vor der Unterschrift steuerlich prüfen.",
  },
  {
    q: "Was ist, wenn ich die Fläche bereits an einen Landwirt verpachtet habe?",
    a: "Das ist häufig. Landpachtverträge lassen sich meist mit Frist kündigen oder für Teilflächen anpassen. Wir planen die Kündigungsfristen in den Zeitplan ein und sprechen auf Wunsch mit Ihrem Pächter – oft kann er die Pflege der Fläche, etwa durch Beweidung, übernehmen.",
  },
  {
    q: "Wie sicher ist der Rückbau nach 30 Jahren?",
    a: "Die Rückbaupflicht steht im Vertrag und in der Dienstbarkeit. Zusätzlich hinterlegt der Betreiber vor Baubeginn eine Rückbaubürgschaft einer Bank oder Versicherung. Fällt der Betreiber aus, kann aus der Bürgschaft zurückgebaut werden.",
  },
];

export default function FlaecheVerpachtenPage() {
  return (
    <div>
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{
          __html: JSON.stringify({
            "@context": "https://schema.org",
            "@type": "Service",
            name: "Pacht von Flächen für Solarparks",
            serviceType: "Flächenpacht für Freiflächen-Photovoltaik",
            provider: { "@id": `${abs("/")}/#organization` },
            areaServed: ["DE", "AT", "CH"],
            audience: { "@type": "Audience", audienceType: "Flächeneigentümer und Landwirte" },
            url: abs(PFAD),
            description: BESCHREIBUNG,
          }),
        }}
      />

      <Hero />
      <Faktenleiste titel="Eckdaten der Solarpacht" fakten={FAKTEN} />
      <Pachtmodelle />
      <Vertrag />
      <Steuern />
      <Pruefung />
      <Weg />
      <Anfrage />

      <Section tone="white" space="lg">
        <div className="grid gap-12 lg:grid-cols-[0.8fr_1.2fr] lg:gap-20">
          <SectionHeading eyebrow="Häufige Fragen" title="Fragen von Flächeneigentümern" lead="Ihre Frage ist nicht dabei? Stellen Sie sie im Formular – wir antworten persönlich." />
          <Faq items={FAQ} />
        </div>
      </Section>

      <Querverweise
        items={[
          { href: "/rechner/pacht", titel: "Pachtrechner", text: "Fest, indexiert oder Umsatzbeteiligung – Ihre Pacht über 30 Jahre im Vergleich zum Ackerbau." },
          { href: "/flaechencheck", titel: "Flächencheck", text: "Ampel, Leistung und Pachtspanne Ihrer Fläche in zwei Minuten." },
          { href: "/dachflaeche-verpachten", titel: "Dachfläche verpachten", text: "Gewerbe-, Hallen- und Stalldächer ab etwa 1.000 m² – Pacht, Dachstrom oder Sanierung als Gegenleistung." },
          { href: "/landwirte", titel: "Für Landwirte", text: "Verpachten, selbst investieren oder beteiligen – die vier Wege mit Agri-PV." },
          { href: "/ratgeber/solarpark-pacht-pro-hektar", titel: "Solarpark-Pacht pro Hektar", text: "Spannen, Einflussfaktoren und ein Rechenbeispiel für 2026." },
          { href: "/ratgeber/pachtvertrag-solarpark", titel: "Pachtvertrag Solarpark", text: "Die wichtigsten Klauseln und eine Checkliste für Eigentümer." },
        ]}
      />

      <CtaBand
        eyebrow="Für Flächeneigentümer kostenfrei"
        title="Was ist Ihre Fläche als Solarpark wert?"
        text="Zwei Minuten im Flächencheck – mit Ampel, möglicher Leistung und Pachtspanne. Das Ergebnis landet auf Wunsch direkt bei unserem Flächenteam."
        primary={{ label: "Zum Flächencheck", href: "/flaechencheck" }}
        secondary={{ label: "Pachtrechner", href: "/rechner/pacht" }}
      />
    </div>
  );
}
// src/app/rechner/pacht/page.js – Pachtrechner Solarpark

import Link from "next/link";
import RechnerSeite, { rechnerMetadata } from "@/components/Rechner/RechnerSeite";
import PachtRechner from "@/components/Flaeche/PachtRechner";
import SectionHeading from "@/components/ui/SectionHeading";
import Reveal from "@/components/ui/Reveal";
import { JahresSaeulen } from "@/components/Flaeche/Verpachten/Pachtmodelle";
import { pachtRechnung } from "@/lib/rechner/pacht";
import { ERLOESE, FREIFLAECHE, PACHT } from "@/lib/invest/markt";
import { fmt } from "@/lib/rechner/annahmen";

const PFAD = "/rechner/pacht";

export const metadata = rechnerMetadata({
  pfad: PFAD,
  title: "Pachtrechner Solarpark: Pacht über 30 Jahre | ÖkoInvest",
  description:
    "Solarpark-Pacht berechnen: Festpacht, indexiert oder Umsatzbeteiligung über 30 Jahre – im Vergleich zu Ackerpacht und Deckungsbeitrag. Kostenlos.",
  keywords: ["Pachtrechner Solarpark", "Solarpark Pacht berechnen", "Umsatzpacht Solarpark", "Pacht indexiert Photovoltaik", "Freiflächen PV Pacht"],
});

const FAQ = [
  {
    q: "Wie viel Pacht pro Hektar zahlt ein Solarpark?",
    a: `Im DACH-Raum liegen Solarpachten derzeit meist zwischen ${fmt(PACHT.freiflaecheProHa.min)} und ${fmt(PACHT.freiflaecheProHa.max)} € je Hektar und Jahr. Hohe Werte gibt es für große Flächen mit nahem Netzanschluss in der EEG-Kulisse, niedrigere bei langen Kabeltrassen, kleinen Flächen oder schwierigem Baurecht.`,
  },
  {
    q: "Was ist besser: Festpacht oder Umsatzbeteiligung?",
    a: `Festpacht ist planbar und unabhängig vom Strompreis. Eine Umsatzbeteiligung von ${fmt(PACHT.umsatzbeteiligung.min * 100)}–${fmt(PACHT.umsatzbeteiligung.max * 100)} % lässt Sie an steigenden Strompreisen teilhaben, schwankt aber mit Ertrag und Preis. Viele Eigentümer wählen eine Kombination: Umsatzbeteiligung mit Mindestpacht – oder eine indexierte Festpacht.`,
  },
  {
    q: "Warum ist die Solarpacht so viel höher als die Ackerpacht?",
    a: `Weil auf einem Hektar rund ${fmt(1 / FREIFLAECHE.haProMwp, 1)} MWp Leistung stehen, die jährlich Strom für mehrere zehntausend Euro erzeugen. Die Pacht ist nur ein kleiner Teil davon. Dafür ist die Fläche 30 Jahre gebunden – die Rückgabe ist über Vertrag, Grundbuch und Rückbaubürgschaft gesichert.`,
  },
  {
    q: "Ist die Pacht vor Baubeginn schon fällig?",
    a: `Nein, die volle Pacht beginnt in der Regel mit dem Bau oder der Inbetriebnahme. Bis dahin zahlen wir meist eine Reservierungsprämie von ${fmt(PACHT.reservierungProHa.min)}–${fmt(PACHT.reservierungProHa.max)} € je Hektar und Jahr, und Sie bewirtschaften weiter. Das können Sie im Rechner über „Vorlauf bis Baubeginn“ abbilden.`,
  },
  {
    q: "Wie wird die Pacht versteuert?",
    a: "Pachteinnahmen sind einkommensteuerpflichtig. Zudem kann die Verpachtung für einen Solarpark Grund- und Erbschaftsteuer beeinflussen. Der Rechner zeigt Werte vor Steuern – lassen Sie Ihren Fall vor Vertragsschluss von Ihrer Steuerberatung prüfen.",
  },
];

/** Mini-Vergleich der drei Modelle (Beispiel 10 ha, Süd-DE, Standardwerte des Rechners) */
function ModellMinis() {
  const reihen = [
    { t: "Festpacht", x: "gleichbleibend", r: pachtRechnung({ modell: "fest" }), ton: "fill-ov-400" },
    { t: "Indexiert", x: `+${fmt(PACHT.indexierung * 100, 1)} % p. a.`, r: pachtRechnung({ modell: "index" }), ton: "fill-ov-600" },
    { t: "Umsatz", x: "6 % der Erlöse", r: pachtRechnung({ modell: "umsatz", umsatzAnteil: 0.06 }), ton: "fill-navy-500" },
  ];
  const max = Math.max(...reihen.flatMap((m) => m.r.jahre.map((j) => j.solar)));
  return (
    <Reveal className="mt-8 grid max-w-2xl gap-3 sm:grid-cols-3">
      {reihen.map((m) => (
        <div key={m.t} className="rounded-2xl bg-sand-50 p-4 ring-1 ring-ink-200/60">
          <p className="font-display text-[15.5px] font-bold text-ink-900">{m.t}</p>
          <p className="text-[12.5px] text-ink-600">{m.x}</p>
          <div className="mt-3 rounded-xl bg-white px-2.5 pb-1.5 pt-2.5 ring-1 ring-ink-200/70">
            <JahresSaeulen jahre={m.r.jahre} max={max} ton={m.ton} />
          </div>
          <p className="mt-2 flex items-baseline justify-between text-[12.5px] text-ink-600">
            <span>Jahr 1–{PACHT.laufzeit}</span>
            <span className="ov-num font-bold text-ink-900">{fmt(Math.round(m.r.summeSolar / 1000))} Tsd. €</span>
          </p>
        </div>
      ))}
      <p className="text-[12.5px] leading-relaxed text-ink-500 sm:col-span-3">Beispiel 10 ha in Süddeutschland mit den Standardwerten des Rechners; jede Säule ist ein Jahr. Nominal, vor Steuern.</p>
    </Reveal>
  );
}

